def confirm_existing(apps, schema_editor):
    """Every refund/transfer recorded before approvals existed already posted
    its journal entry: it is confirmed. Who approved it is unknown, so
    confirmed_by stays empty; confirmed_at is when it was recorded."""
    for name in ('ClientRefund', 'ClientTransfer'):
        model = apps.get_model('hw', name)
        for doc in model.objects.all().only('pk', 'created_at'):
            model.objects.filter(pk=doc.pk).update(status='confirmed', confirmed_at=doc.created_at)


